let feedQueue=Promise.resolve();
function feedName(id){return id==='me'?profile.name:chatLabel(id)}
function feedCandidates(m,parent=null){return PalaisSocial.candidates(relations,roles,m,parent)}
function renderMoments(){screen.innerHTML=`<section class="view">${wxHeading('朋友圈','WECHAT · MOMENTS','<button class="round" id="newMoment" aria-label="发布动态">+</button>')}<div class="moment-cover"><span>❀</span><h3>把日常，酿成温柔。</h3><p>相遇以后，故事开始交织</p></div><label class="check feed-auto"><input id="autoSocial" type="checkbox" ${socialSettings.auto?'checked':''}>发布与评论后，角色自动互动</label><div class="actions"><select id="momentRole" aria-label="选择发布动态的角色">${roles.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select><button class="secondary" id="roleMoment" ${socialBusy?'disabled':''}>${socialBusy?'角色正在互动…':'生成角色动态'}</button></div><p class="api-note">只有认识的角色才互评。同群后自动认识，也可在世界书登记原有关系。每次动态自动生成至多 3 条评论和 1 条互相回复；评论后最多补 1 条回复，均调用聊天 API。</p><div id="momentList"></div></section>`;bindWxHome();$('#newMoment').onclick=createMoment;$('#autoSocial').onchange=e=>{socialSettings={...socialSettings,auto:e.target.checked};saveSocial();toast(socialSettings.auto?'已开启角色自动互动':'已关闭自动互动，可手动请角色评论')};$('#roleMoment').onclick=generateRoleMoment;
  const list=$('#momentList');if(!moments.length)list.innerHTML='<div class="soft-empty">发布第一条动态，收藏今天。</div>';moments.forEach(m=>{const r=roles.find(r=>r.id===m.author),card=document.createElement('article');card.className='moment-card';card.innerHTML=`<div class="moment-person">${avatarHTML(m.author==='me'?'profile':'role:'+m.author,r?.emoji||'🎀')}<div><strong>${escapeHtml(feedName(m.author))}</strong><small>${new Date(m.createdAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></div></div><p>${escapeHtml(m.text)}</p>${mediaCache.has('moment:'+m.id)?`<img class="moment-photo" alt="动态配图" src="${mediaCache.get('moment:'+m.id)}">`:''}<div class="moment-tools"><button class="text-button like">${m.liked?'♥ 已喜欢':'♡ 喜欢'}</button><button class="text-button comment">评论</button><button class="text-button ai-comment" ${feedCandidates(m).length?'':'disabled'}>角色评论</button><button class="text-button remove">删除</button></div><div class="moment-comments"></div>`;
    card.querySelector('.like').onclick=()=>{m.liked=!m.liked;saveSocial();renderMoments()};card.querySelector('.comment').onclick=()=>commentMoment(m);card.querySelector('.ai-comment').onclick=()=>commentMoment(m,true);card.querySelector('.remove').onclick=()=>deleteMoment(m);const comments=card.querySelector('.moment-comments');(m.comments||[]).forEach(c=>{const parent=m.comments.find(x=>x.id===c.parentId),row=document.createElement('div');row.className='thread-comment'+(parent?' thread-reply':'');row.innerHTML=`<p><strong>${escapeHtml(feedName(c.author))}</strong>${parent?` <span>回复</span> <strong>${escapeHtml(feedName(parent.author))}</strong>`:''}：${escapeHtml(c.text)}</p><div class="thread-tools"><button class="text-button user-reply">回复</button><button class="text-button role-reply" ${feedCandidates(m,c).length?'':'disabled'}>请角色回复</button></div>`;row.querySelector('.user-reply').onclick=()=>commentMoment(m,false,c.id);row.querySelector('.role-reply').onclick=()=>commentMoment(m,true,c.id);comments.append(row)});list.append(card)});
}
async function generateRoleMoment(){if(!requireAPI())return;const r=roles.find(r=>r.id===$('#momentRole').value);if(!r){toast('先创建角色');return}const b=$('#roleMoment');b.disabled=true;b.textContent='正在构思…';try{const text=await request({...config,key},[{role:'system',content:PalaisCore.systemPrompt(r,worldbook,[])+'\n'+relationshipPrompt(r.id)+'\n'+sharedContext(r.id)+'\n你要发布一条符合人设的朋友圈动态。只写20–100字正文，不使用红包格式。只分享自己的日常或公开经历，不透露私聊或替其他角色编造关系。'},{role:'user',content:'写一条今天的日常动态。'}],400);const m={id:crypto.randomUUID(),author:r.id,text,createdAt:Date.now(),liked:false,comments:[]};commitMoment(m);if(isMomentsView())renderMoments();toast('角色动态已生成');queueInteractions(m)}catch(err){toast(friendly(err))}finally{b.disabled=false;b.textContent='生成角色动态'}}
function commitMoment(m){const previous=moments,log=feedEvents.slice();try{moments=[m,...moments];recordFeed(m);saveSocial()}catch(err){moments=previous;feedEvents=log;throw err}}
function createMoment(){const id=crypto.randomUUID(),d=panel(`<form id="momentForm"><h2>今天的小片刻</h2><label>动态内容<textarea name="text" required maxlength="3000" rows="5" placeholder="写下今天想留住的瞬间…"></textarea></label>${fileInput('momentFile')}<div id="momentImagePreview"></div><button class="text-button" type="button" id="chooseMomentPhoto">＋ 添加一张图片</button><div class="actions"><button type="button" class="secondary" id="cancelMoment">取消</button><button class="primary" id="publishMoment">发布动态</button></div></form>`);let image=null;$('#cancelMoment').onclick=()=>d.close();$('#chooseMomentPhoto').onclick=()=>$('#momentFile').click();$('#momentFile').onchange=async e=>{const b=$('#publishMoment');b.disabled=true;try{image=await prepareImage(e.target.files[0],1200);$('#momentImagePreview').innerHTML=`<img alt="动态图片预览" class="moment-photo" src="${image}">`}catch(err){toast(err.message)}finally{b.disabled=false}};$('#momentForm').onsubmit=async e=>{e.preventDefault();const text=e.target.text.value.trim();if(!text)return;const b=$('#publishMoment');b.disabled=true;try{if(image)await mediaWrite('moment:'+id,image);const m={id,author:'me',text,createdAt:Date.now(),liked:false,comments:[]};commitMoment(m);d.close();renderMoments();toast('动态已发布');queueInteractions(m)}catch(err){toast(err.message)}finally{b.disabled=false}}}
function commitComment(m,c){const log=feedEvents.slice();m.comments.push(c);try{recordFeed(m,c);saveSocial()}catch(err){m.comments.pop();feedEvents=log;throw err}}
async function generateComment(m,author,parent=null){const r=roles.find(r=>r.id===author);if(!r||!feedCandidates(m,parent).some(x=>x.id===author))throw Error('这个角色尚不认识动态或评论的作者，不能互动');const text=await request({...config,key},[{role:'system',content:PalaisCore.systemPrompt(r,worldbook,[])+'\n'+relationshipPrompt(author)+'\n'+sharedContext(author)+'\n根据人设参与朋友圈。只输出自然的中文评论或回复，1–3句话，不使用红包格式。只知道下面展示的可见内容，不猜测没有见过的评论，不透露私聊。'+(parent?'这次明确回复「'+feedName(parent.author)+'」的评论：'+parent.text:'这次评论动态正文。')},{role:'user',content:feedContext(author,m)}],400);if(!moments.some(x=>x.id===m.id))throw Error('动态已删除，未保存回复');const c={id:crypto.randomUUID(),author,text,parentId:parent?.id||null,createdAt:Date.now()};commitComment(m,c);if(isMomentsView())renderMoments();memoryTick();return c}
function commentMoment(m,ai=false,parentId=null){const parent=parentId?m.comments.find(x=>x.id===parentId):null,candidates=feedCandidates(m,parent);if(ai&&!candidates.length){toast('还没有认识对方的角色可以回复');return}const d=panel(`<form id="commentForm"><h2>${parent?'回复 '+escapeHtml(feedName(parent.author)):ai?'请角色评论':'留一句话'}</h2>${parent?`<div class="reply-preview">${escapeHtml(parent.text)}</div>`:''}${ai?`<label>选择角色<select name="roleId">${candidates.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select></label><p class="api-note">这里只显示认识动态作者和目标评论作者的角色。</p>`:'<label>评论<textarea name="text" required rows="3" maxlength="1000"></textarea></label>'}<div class="actions"><button type="button" class="secondary" id="cancelComment">取消</button><button class="primary" id="submitComment">${ai?'生成回复':'发布回复'}</button></div></form>`);$('#cancelComment').onclick=()=>d.close();$('#commentForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=$('#submitComment');b.disabled=true;try{let c;if(ai){if(!apiReady())throw Error('请先连接聊天 API');c=await generateComment(m,f.roleId.value,parent)}else{const text=f.text.value.trim();if(!text)return;c={id:crypto.randomUUID(),author:'me',text,parentId:parent?.id||null,createdAt:Date.now()};commitComment(m,c)}d.close();if(isMomentsView())renderMoments();toast('回复已保存');queueInteractions(m,c)}catch(err){toast(friendly(err))}finally{b.disabled=false}}}
function queueInteractions(m,c=null){if(!socialSettings.auto||!apiReady())return;feedQueue=feedQueue.then(async()=>{if(!socialSettings.auto||!moments.some(x=>x.id===m.id))return;socialBusy=true;if(isMomentsView())renderMoments();try{if(c){const candidates=feedCandidates(m,c).filter(r=>r.id!==c.author),responder=candidates.find(r=>r.id===m.author)||candidates.find(r=>r.id===(c.parentId?m.comments.find(x=>x.id===c.parentId)?.author:null))||candidates[0];if(responder)await generateComment(m,responder.id,c)}else{const candidates=feedCandidates(m).filter(r=>r.id!==m.author).slice(0,3);let first=null;for(const r of candidates){if(!socialSettings.auto)break;const reply=await generateComment(m,r.id);first=first||reply}if(first&&socialSettings.auto){const peer=feedCandidates(m,first).find(r=>r.id!==first.author&&r.id!=='me');if(peer)await generateComment(m,peer.id,first)}}}catch(err){toast('角色互动未完成：'+friendly(err)+'，已生成内容会保留')}finally{socialBusy=false;if(isMomentsView())renderMoments();memoryTick()}}).catch(err=>toast(friendly(err)));}
function deleteMoment(m){const d=panel('<h2>删除这条动态？</h2><p class="api-note">动态和评论将移出朋友圈，角色已形成的共同经历记忆会保留。</p><div class="actions"><button class="secondary" id="keepMoment">取消</button><button class="primary" id="deleteMoment">删除</button></div>');$('#keepMoment').onclick=()=>d.close();$('#deleteMoment').onclick=async()=>{const previous=moments;try{moments=moments.filter(x=>x.id!==m.id);saveSocial();d.close();if(isMomentsView())renderMoments();await mediaWrite('moment:'+m.id,null)}catch(err){moments=previous;toast(err.message)}}}
